#!/bin/sh # Fan out local mainline to every push target in the manifest. # There is deliberately NO --force here. A non-fast-forward target # is a divergence to investigate by hand, never something to clobber. set -eu branch=main
# read_targets emits: "<name> <url> <mode>" per line from the manifest. read_targets | while read -r name url mode; do [ "$mode" = "push" ] || { echo "$name: skip ($mode)"; continue; }
# Fail-loud ancestry gate: the target's main must be an ancestor # of local mainline, or we refuse to touch it. remote_head=$(git ls-remote "$url" "refs/heads/$branch" | cut -f1) if [ -n "$remote_head" ] && ! git merge-base --is-ancestor "$remote_head" "$branch"; then echo "$name: DRIFT — host has commits mainline lacks; reconcile by hand" continue fi
# Fast-forward-only push. No '+', no --force, ever. if git push "$url" "$branch:$branch" && git push --tags "$url"; then echo "$name: ok" else echo "$name: push failed" fi done
